INSERT INTO `announcements` (`id`, `user_id`, `title`, `body`, `audience`, `level`, `is_published`, `expires_at`, `created_at`, `updated_at`) VALUES (1,1,'Mango season is here 🥭','Sindhri and Chaunsa are arriving at the Tando Jam, Latifabad and Paretabad markets this week. Pre-order early — they sell out by noon!','all','success',1,NULL,'2026-09-26 08:30:38','2026-09-26 08:30:38'),(2,1,'Update your pickup windows','Please review your pickup slots for the upcoming public holiday. Markets will run on normal hours.','farmers','warning',1,NULL,'2026-09-26 08:30:38','2026-09-26 08:30:38');
