INSERT INTO `contact_messages` (`id`, `name`, `email`, `subject`, `message`, `ip_address`, `is_read`, `created_at`, `updated_at`) VALUES (1,'Bilal Hussain','bilal.h@example.com','Can I sell at the Qasimabad market?','I run a small organic farm in Thatta and would love to join. What is the process?',NULL,0,'2026-09-26 08:30:38','2026-09-26 08:30:38'),(2,'Rabia Khan','rabia@example.com','Great platform!','Pre-ordering my weekly veggies saved me so much time. Please add more markets in Gulistan-e-Jauhar.',NULL,0,'2026-09-26 08:30:38','2026-09-26 08:30:38'),(3,'Tariq Aziz','tariq@example.com','Pickup timing question','Is there any flexibility if I am 15 minutes late to my pickup window?',NULL,0,'2026-09-26 08:30:38','2026-09-26 08:30:38');
