INSERT INTO `farmer_profiles` (`id`, `user_id`, `stall_name`, `slug`, `contact_person`, `phone`, `email`, `address`, `tagline`, `bio`, `latitude`, `longitude`, `operating_days`, `order_cutoff_hours`, `logo`, `cover_image`, `status`, `approved_at`, `status_reason`, `rating_avg`, `rating_count`, `created_at`, `updated_at`) VALUES (1,2,'Green Acres Organic Farm','green-acres-organic-farm','Ali Raza','+92 325 5413892','farmer@gleangrid.test','Farm road, Hyderabad outskirts','Chemical-free vegetables from the fields of Tando Jam since 2009.','Chemical-free vegetables from the fields of Tando Jam since 2009. We bring our harvest to Qasimabad Sunday Farmers Market, Auto Bhan Greens Market and Latifabad Organic Bazaar. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.43120000,68.52050000,'[0,3,6]',12,'produce:carrot',NULL,'approved','2026-06-28 08:30:28',NULL,3.63,8,'2026-09-26 08:30:28','2026-09-26 08:30:38'),(2,3,'Sindh Valley Orchards','sindh-valley-orchards','Fatima Memon','+92 341 2296008','fatima@gleangrid.test','Farm road, Hyderabad outskirts','Three generations of fruit growers from Tando Allahyar.','Three generations of fruit growers from Tando Allahyar. We bring our harvest to Latifabad Organic Bazaar, Paretabad Farmers Mela and Tando Jam Countryside Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.46000000,68.71000000,'[0,2,4,6]',18,'produce:mango',NULL,'approved','2026-06-29 08:30:28',NULL,4.83,6,'2026-09-26 08:30:28','2026-09-26 08:30:34'),(3,4,'Thar Dairy Collective','thar-dairy-collective','Kamran Baloch','+92 325 8943751','kamran@gleangrid.test','Farm road, Hyderabad outskirts','Grass-fed milk from a cooperative of 40 small herders.','Grass-fed milk from a cooperative of 40 small herders. We bring our harvest to Qasimabad Sunday Farmers Market, Latifabad Organic Bazaar and Tando Jam Countryside Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.35210000,68.44100000,'[0,4,6]',24,'produce:glass_of_milk',NULL,'approved','2026-06-30 08:30:29',NULL,4.20,5,'2026-09-26 08:30:29','2026-09-26 08:30:35'),(4,5,'Hilltop Bakehouse','hilltop-bakehouse','Sara Khan','+92 330 8483116','sara@gleangrid.test','Farm road, Hyderabad outskirts','Slow-fermented breads baked in a wood-fired oven in Latifabad.','Slow-fermented breads baked in a wood-fired oven in Latifabad. We bring our harvest to Qasimabad Sunday Farmers Market, Hirabad Evening Harvest Market and Latifabad Organic Bazaar. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.37450000,68.36110000,'[0,5,6]',12,'produce:bread',NULL,'approved','2026-07-01 08:30:29',NULL,3.89,9,'2026-09-26 08:30:29','2026-09-26 08:30:38'),(5,6,'Kirthar Honey Co.','kirthar-honey-co','Imran Shah','+92 334 3282402','imran@gleangrid.test','Farm road, Hyderabad outskirts','Wild honey from the Kirthar range, never heated or blended.','Wild honey from the Kirthar range, never heated or blended. We bring our harvest to Latifabad Organic Bazaar, Hirabad Evening Harvest Market and Saddar Heritage Produce Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.70000000,67.60000000,'[0,1,2,3,4,5,6]',18,'produce:honey_pot',NULL,'approved','2026-07-02 08:30:29',NULL,3.30,10,'2026-09-26 08:30:29','2026-09-26 08:30:37'),(6,7,'Kotri Herb Garden','kotri-herb-garden','Ayesha Siddiqui','+92 319 2692119','ayesha@gleangrid.test','Farm road, Hyderabad outskirts','Tender herbs and leafy greens from the Indus banks at Kotri, cut to order.','Tender herbs and leafy greens from the Indus banks at Kotri, cut to order. We bring our harvest to Auto Bhan Greens Market, Tando Jam Countryside Market and Qasimabad Sunday Farmers Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.36550000,68.30800000,'[0,3,4]',24,'produce:herb',NULL,'approved','2026-07-03 08:30:29',NULL,4.00,8,'2026-09-26 08:30:29','2026-09-26 08:30:37'),(7,8,'Indus Delta Farms','indus-delta-farms','Bilal Ahmed','+92 340 3909727','bilal@gleangrid.test','Farm road, Hyderabad outskirts','Heritage rice and pulses from Thatta.','Heritage rice and pulses from Thatta. We bring our harvest to Saddar Heritage Produce Market and Paretabad Farmers Mela. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',24.74700000,67.92400000,'[1,2,3,4,5,6]',12,'produce:sheaf_of_rice',NULL,'approved','2026-07-04 08:30:29',NULL,4.27,11,'2026-09-26 08:30:29','2026-09-26 08:30:38'),(8,9,'Sunrise Poultry & Eggs','sunrise-poultry-eggs','Usman Qureshi','+92 312 9621609','usman@gleangrid.test','Farm road, Hyderabad outskirts','Pasture-raised desi eggs from Hatri.','Pasture-raised desi eggs from Hatri. We bring our harvest to Paretabad Farmers Mela and Saddar Heritage Produce Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.45200000,68.40100000,'[1,2,3,4,5,6]',18,'produce:egg',NULL,'approved','2026-07-05 08:30:29',NULL,4.29,7,'2026-09-26 08:30:29','2026-09-26 08:30:37'),(9,10,'Bloom & Stem','bloom-stem','Hina Ali','+92 317 7276892','hina@gleangrid.test','Farm road, Hyderabad outskirts','Seasonal flowers grown without chemical sprays.','Seasonal flowers grown without chemical sprays. We bring our harvest to Hirabad Evening Harvest Market and Qasimabad Sunday Farmers Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.41050000,68.33500000,'[0,5,6]',24,'produce:sunflower',NULL,'approved','2026-07-06 08:30:29',NULL,4.25,4,'2026-09-26 08:30:29','2026-09-26 08:30:38'),(10,11,'Jamshoro River Growers','jamshoro-river-growers','Zainab Farooq','+92 311 5030531','zainab@gleangrid.test','Farm road, Hyderabad outskirts','Everyday kitchen staples at fair prices.','Everyday kitchen staples at fair prices. We bring our harvest to Saddar Heritage Produce Market, Paretabad Farmers Mela and Auto Bhan Greens Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.43000000,68.28100000,'[0,1,2,3,4,5,6]',12,'produce:potato',NULL,'approved','2026-07-07 08:30:29',NULL,4.20,5,'2026-09-26 08:30:29','2026-09-26 08:30:34'),(11,12,'Mirpurkhas Mango House','mirpurkhas-mango-house','Saad Jamali','+92 348 6796153','saad@gleangrid.test','Farm road, Hyderabad outskirts','Tropical fruit from the orchards of Mirpurkhas.','Tropical fruit from the orchards of Mirpurkhas. We bring our harvest to Tando Jam Countryside Market, Latifabad Organic Bazaar and Hirabad Evening Harvest Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.52700000,69.01100000,'[0,4,5,6]',18,'produce:mango',NULL,'approved','2026-07-08 08:30:29',NULL,3.86,7,'2026-09-26 08:30:29','2026-09-26 08:30:37'),(12,13,'Coastal Greens','coastal-greens','Nadia Hussain','+92 336 4863378','nadia@gleangrid.test','Farm road, Hyderabad outskirts','Hydroponic lettuce and berries from Matiari.','Hydroponic lettuce and berries from Matiari. We bring our harvest to Qasimabad Sunday Farmers Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.59700000,68.44600000,'[0]',24,'produce:strawberry',NULL,'pending',NULL,NULL,0.00,0,'2026-09-26 08:30:29','2026-09-26 08:30:29'),(13,14,'Quick Veg Traders','quick-veg-traders','Rashid Mehmood','+92 329 9921722','rashid@gleangrid.test','Farm road, Hyderabad outskirts','Wholesale vegetables.','Wholesale vegetables. We bring our harvest to Saddar Heritage Produce Market. Every item on this stall is grown or made by our own family and team — ask us anything at the stall.',25.38900000,68.37200000,'[1,2,3,4,5,6]',12,'produce:basket',NULL,'suspended',NULL,'Repeated customer complaints about quality.',0.00,0,'2026-09-26 08:30:29','2026-09-26 08:30:29');
